package org.local.donusturucu.qa;
import android.app.*;import android.content.*;import android.os.*;import android.widget.*;import java.io.*;import org.json.*;
public class SubtitleControls extends FileList {
 public void onStart(){Bundle result=new Bundle();try{Intent i=new Intent();i.setClassName("org.local.donusturucu","org.local.donusturucu.MainActivity");i.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);activity=startActivitySync(i);long until=System.currentTimeMillis()+60000;while(!(Boolean)get("ready")&&System.currentTimeMillis()<until)Thread.sleep(200);require((Boolean)get("ready"));File root=new File(getTargetContext().getExternalFilesDir(null),"subtitle-controls-test");root.mkdirs();File audio=new File(root,"Ceviri.txt");Writer text=new OutputStreamWriter(new FileOutputStream(audio),"UTF-8");text.write("Merhaba\n");text.close();load(audio,1);JSONArray rows=new JSONArray();
 for(int repeat=1;repeat<=3;repeat++)for(final boolean ku:new boolean[]{false,true}){ui(new Runnable(){public void run(){try{set("ku",ku);set("action","subtitle_restore");call("build",new Class<?>[]{});require(((java.util.List)get("actionIds")).contains("subtitle_restore"));require(get("otherButton")!=null&&get("begin")==null);set("busy",true);call("controls",new Class<?>[]{});require(!((Button)get("otherButton")).isEnabled());set("busy",false);call("controls",new Class<?>[]{});require(((Button)get("otherButton")).isEnabled());}catch(Exception e){throw new RuntimeException(e);}}});JSONObject row=new JSONObject();row.put("repeat",repeat);row.put("language",ku?"ku":"tr");row.put("pass",true);rows.put(row);}
 JSONObject report=new JSONObject();report.put("cases",rows.length());report.put("failures",0);report.put("rows",rows);Writer w=new OutputStreamWriter(new FileOutputStream(new File(root,"report.json")),"UTF-8");w.write(report.toString(2));w.close();finish(0,result);
 }catch(Throwable e){result.putString("error",e.toString());finish(1,result);}}
}
